  "Waterline beam": { es: "Manga en flotación", ar: "عرض خط الماء", zh: "水线宽", sw: "Upana wa mstari wa maji", sv: "Vattenlinjebredd" },
  "GM (initial stability)": { es: "GM (estabilidad inicial)", ar: "GM (الثبات الأولي)", zh: "GM（初稳性）", sw: "GM (uthabiti wa awali)", sv: "GM (initialstabilitet)" },
  "Max righting arm": { es: "Brazo adrizante máximo", ar: "أقصى ذراع استعدال", zh: "最大复原力臂", sw: "Mkono wa kunyoosha wa juu", sv: "Största rätande hävarm" },
  "Estimated top speed": { es: "Velocidad máxima estimada", ar: "السرعة القصوى المقدّرة", zh: "估计最高航速", sw: "Kasi ya juu inayokadiriwa", sv: "Uppskattad toppfart" },
