  "Ballast (lead/iron) in keel": { es: "Lastre (plomo/hierro) en la quilla", ar: "ثقل (رصاص/حديد) في العارضة", zh: "龙骨内压载（铅／铁）", sw: "Uzito (risasi/chuma) ndani ya mkuku", sv: "Barlast (bly/järn) i kölen" },
  "Rudder and tiller": { es: "Timón y caña", ar: "الدفة والمقبض", zh: "舵和舵柄", sw: "Usukani na mpini", sv: "Roder och rorkult" },
