  "US rule of thumb:": { es: "Regla práctica de EE. UU.:", ar: "القاعدة التقريبية الأمريكية:", zh: "美国经验法则：", sw: "Kanuni ya kawaida ya Marekani:", sv: "Amerikansk tumregel:" },
  "Sail area / displacement": { es: "Superficie vélica / desplazamiento", ar: "مساحة الشراع / الإزاحة", zh: "帆面积／排水量", sw: "Eneo la tanga / uzito", sv: "Segelyta / deplacement" },
  "❌ Overloaded: the boat cannot carry": { es: "❌ Sobrecargado: el barco no puede llevar", ar: "❌ حمولة زائدة: لا يستطيع القارب حمل", zh: "❌ 超载：船无法承载", sw: "❌ Mzigo kupita kiasi: boti haiwezi kubeba", sv: "❌ Överlastad: båten kan inte bära" },
  "❌ Water comes over the deck edge. Reduce the load, move weight, or add depth.": { es: "❌ El agua entra por el borde de la cubierta. Reduce la carga, mueve peso o añade puntal.", ar: "❌ يدخل الماء من حافة السطح. خفّف الحمولة أو حرّك الوزن أو زد العمق.", zh: "❌ 水漫过甲板边缘。请减少载荷、移动重量或增加型深。", sw: "❌ Maji yanaingia juu ya ukingo wa sitaha. Punguza mzigo, sogeza uzito au ongeza kina.", sv: "❌ Vatten kommer över däckskanten. Minska lasten, flytta vikt eller öka djupet." },
  "⚠️ Low freeboard (": { es: "⚠️ Francobordo bajo (", ar: "⚠️ طفو حر منخفض (", zh: "⚠️ 干舷过低（", sw: "⚠️ Urefu juu ya maji mdogo (", sv: "⚠️ Lågt fribord (" },
  "✅ Freeboard": { es: "✅ Francobordo", ar: "✅ الطفو الحر", zh: "✅ 干舷", sw: "✅ Urefu juu ya maji", sv: "✅ Fribord" },
  "⚠️ Trimmed": { es: "⚠️ Asiento de", ar: "⚠️ ميل طولي", zh: "⚠️ 纵倾", sw: "⚠️ Imeinama", sv: "⚠️ Trimmad" },
  "(LCG is at": { es: "(el LCG está en", ar: "(LCG عند", zh: "（LCG 位于", sw: "(LCG iko", sv: "(LCG ligger på" },
  "❌ Negative GM: the boat would roll over. Lower the weights, add ballast or beam.": { es: "❌ GM negativo: el barco volcaría. Baja los pesos, añade lastre o manga.", ar: "❌ GM سالب: سينقلب القارب. اخفض الأوزان أو أضف ثقلًا أو عرضًا.", zh: "❌ GM 为负：船会倾覆。请降低重量、增加压载或船宽。", sw: "❌ GM hasi: boti ingepinduka. Shusha uzito, ongeza uzito wa ziada au upana.", sv: "❌ Negativt GM: båten skulle kantra. Sänk vikterna, lägg till barlast eller bredd." },
  "⚠️ Very stiff (GM": { es: "⚠️ Muy rígido (GM", ar: "⚠️ صلب جدًا (GM", zh: "⚠️ 过于刚硬（GM", sw: "⚠️ Imara kupita kiasi (GM", sv: "⚠️ Mycket styv (GM" },
  "✅ Initial stability GM": { es: "✅ Estabilidad inicial GM", ar: "✅ الثبات الأولي GM", zh: "✅ 初稳性 GM", sw: "✅ Uthabiti wa awali GM", sv: "✅ Initialstabilitet GM" },
